// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint8);
}

contract TokenSale {
    IERC20 public saleToken;
    address payable public destinationWallet;
    uint256 public bnbPrice;
    uint256 public minPurchase;
    uint256 public maxPurchase;
    address public owner;

    bool private locked; // Mutex para prevenir reentrancy

    event TokensPurchased(address indexed buyer, uint256 amount, uint256 cost, string paymentMethod);

    // Modificador para restringir acesso ao owner
    modifier onlyOwner() {
        require(msg.sender == owner, "Apenas o dono pode executar esta funcao");
        _;
    }

    // Modificador para prevenir reentrancy
    modifier noReentrancy() {
        require(!locked, "Reentrancy detectada");
        locked = true;
        _;
        locked = false;
    }

    constructor() {
        owner = msg.sender;
        saleToken = IERC20(0xe584f4057284bCc379Af60cE1E34e960FB4BcAFE);
        destinationWallet = payable(0xEe02E32d8d2888E9f1D6d13391E716Bc7F41f6Ae);
        bnbPrice = 1e15; // 0.001 BNB por token
        minPurchase = 1e8;
        maxPurchase = 1000e8;
    }

    // Função para comprar tokens com BNB
    function buy() external payable noReentrancy {
        require(msg.value >= minPurchase, "Valor minimo nao atingido");
        require(msg.value <= maxPurchase, "Valor maximo excedido");

        uint256 tokenAmount = (msg.value * 10**saleToken.decimals()) / bnbPrice;
        require(saleToken.transfer(msg.sender, tokenAmount), "Falha ao transferir tokens");

        // Envia BNB para o destino (usando call para evitar limite de gas do transfer)
        (bool success, ) = destinationWallet.call{value: msg.value}("");
        require(success, "Falha ao enviar BNB");

        emit TokensPurchased(msg.sender, tokenAmount, msg.value, "BNB");
    }

    // Função para atualizar preços (somente owner)
    function updatePrices(uint256 newBnbPrice, uint256 newMinPurchase, uint256 newMaxPurchase) external onlyOwner {
        require(newBnbPrice > 0, "Preco deve ser maior que zero");
        require(newMinPurchase > 0, "Compra minima deve ser maior que zero");
        require(newMaxPurchase >= newMinPurchase, "Compra maxima deve ser >= minima");

        bnbPrice = newBnbPrice;
        minPurchase = newMinPurchase;
        maxPurchase = newMaxPurchase;
    }

    // Função para retirar BNB acumulado (somente owner)
    function emergencyWithdrawBNB() external onlyOwner {
        uint256 amount = address(this).balance;
        require(amount > 0, "Nenhum BNB para retirar");

        (bool success, ) = owner.call{value: amount}("");
        require(success, "Falha ao enviar BNB");
    }

    // Função para atualizar o endereço do token (somente owner)
    function updateSaleToken(address newTokenAddress) external onlyOwner {
        saleToken = IERC20(newTokenAddress);
    }

    // Função para atualizar a carteira de destino (somente owner)
    function updateDestinationWallet(address payable newWallet) external onlyOwner {
        destinationWallet = newWallet;
    }

    // Função para verificar o saldo de tokens do contrato
    function getContractTokenBalance() external view returns (uint256) {
        return saleToken.balanceOf(address(this));
    }
}

